import{_ as s}from"./chunks/flights-route.DhfUIE4N.js";import{_ as a,C as d,o as l,c as o,a3 as r,j as t,E as i}from"./chunks/framework.B9qR_F1m.js";const C=JSON.parse('{"title":"Die Oberfläche","description":"","frontmatter":{},"headers":[],"relativePath":"start/oberflaeche.md","filePath":"start/oberflaeche.md"}'),g={name:"start/oberflaeche.md"},h={class:"tiles"},u={class:"tile",href:"../bereiche/uebersicht"},b={class:"tile-icon"},c={class:"tile",href:"../bereiche/intel"},k={class:"tile-icon"},f={class:"tile",href:"../bereiche/planung"},m={class:"tile-icon"},p={class:"tile",href:"../bereiche/timing"},S={class:"tile-icon"},D={class:"tile",href:"../bereiche/flights"},z={class:"tile-icon"},P={class:"tile",href:"../bereiche/kneeboards"},F={class:"tile-icon"},K={class:"tile",href:"../bereiche/iads"},T={class:"tile-icon"};function _(B,e,A,w,L,M){const n=d("Icon");return l(),o("div",null,[e[16]||(e[16]=r('<h1 id="die-oberflache" tabindex="-1">Die Oberfläche <a class="header-anchor" href="#die-oberflache" aria-label="Permalink to &quot;Die Oberfläche&quot;">​</a></h1><p>Shardwing hat einen festen Aufbau, egal in welchem Bereich du bist: <strong>Leiste oben</strong>, <strong>Liste links</strong>, <strong>Karte in der Mitte</strong>, <strong>Panel darunter</strong>.</p><p><img src="'+s+'" alt="Aufbau der Oberfläche" loading="lazy"></p><h2 id="die-leiste-oben" tabindex="-1">Die Leiste oben <a class="header-anchor" href="#die-leiste-oben" aria-label="Permalink to &quot;Die Leiste oben&quot;">​</a></h2><p>Von links nach rechts:</p><table tabindex="0"><thead><tr><th>Element</th><th>Was es tut</th></tr></thead><tbody><tr><td><strong>Logo-Menü</strong></td><td>Welche Mission offen ist, <strong>Öffnen</strong> (<kbd>⌘O</kbd> / <kbd>Strg+O</kbd>; Ziehen ins Fenster geht auch), <strong>Teilen</strong>, <a href="#suche"><strong>Suchen</strong></a>, <a href="/dcs/speichern#ausgeben"><strong>Ausgeben</strong></a>, <strong>Schließen</strong>, zuletzt geöffnete Missionen, Version. In schmalen Fenstern wandern auch die Anzeige-Schalter hier hinein. Ohne offene Mission steht <strong>Öffnen</strong> zusätzlich in der Leiste.</td></tr><tr><td><strong>Link öffnen</strong></td><td>Im Logo-Menü, nur in der Desktop-App: einen Shardwing-Link einfügen (<kbd>⌘L</kbd> / <kbd>Strg+L</kbd>).</td></tr><tr><td><strong>Schließen</strong></td><td>Im Logo-Menü: Mission schließen, leer neu anfangen.</td></tr><tr><td><strong>Teilen</strong></td><td>Im Logo-Menü und auf dem Ausgeben-Blatt: Mission auf den Server legen und <a href="/gemeinsam/teilen">gemeinsam planen</a>.</td></tr><tr><td><strong>Speichern</strong></td><td>Die .miz schreiben (<kbd>⌘S</kbd> / <kbd>Strg+S</kbd>). Ein Punkt neben dem Dateinamen zeigt ungespeicherte Änderungen. Bei geteilten Missionen speichert der Server jede Änderung sofort: Dort steht der Sync-Status, ein Punkt erscheint nicht.</td></tr><tr><td><strong>Bereiche</strong></td><td>Übersicht · Intel · Planung · Timing · Flights · Kneeboards; daneben, für sich, <strong>IADS</strong> – für Missionen mit eigenem Luftverteidigungsnetz. Gestrichelt, solange die Mission kein IADS-Script hat; mit grünem Punkt, sobald das Script in der Mission steckt oder beim Speichern eingebaut wird.</td></tr><tr><td><strong>Ausgeben</strong></td><td>Das Ende der Leiste: <a href="/dcs/speichern#ausgeben">ein Blatt</a> für alles, was rausgeht – Speichern mit eingebetteten Kneeboards, PDF und Kneeboard-Ordner, Briefing, Teilen (<kbd>⌘E</kbd> / <kbd>Strg+E</kbd>).</td></tr><tr><td><strong>Stand der Bereiche</strong></td><td>Vor jedem Bereich steht ein Punkt: grau = noch nichts da, grün = in Ordnung, blau = Hinweise, rot = prüfen. In breiten Fenstern steht der Stand als Zeile darunter (z. B. „12 von 27 frei“, „H 08:35 L“, „2 von 3 bereit“, „6 Seiten“), sonst im Tooltip.</td></tr><tr><td><strong>Ampel</strong></td><td>Der Stand aller spielbaren Flights in einem Knopf: „bereit“, die Zahl der Hinweise oder der Punkte zum Prüfen. Ein Klick öffnet <strong>Was fehlt noch?</strong> – je Flight die offenen Punkte; ein Klick auf eine Zeile öffnet den Flight im passenden Reiter (Zeiten, Units &amp; Funk, DTC, Lineup Card, sonst Status). Als Flight siehst du nur deinen eigenen. Die Ampel hält niemanden vom Speichern ab.</td></tr><tr><td><strong>Rolle</strong></td><td>„Mission Designer“ – oder die Ansicht als bestimmter Flight. <a href="/gemeinsam/rollen">Mehr zu Rollen</a></td></tr><tr><td><strong>DDM · DMS · DD · MGRS</strong></td><td>Koordinatenformat, überall in der App.</td></tr><tr><td><strong>L · Z</strong></td><td>Zeiten in Ortszeit der Karte (L) oder Zulu (Z).</td></tr><tr><td><strong>UTC±</strong></td><td>Zeitzone der Karte; lässt sich pro Mission korrigieren.</td></tr></tbody></table><h2 id="die-bereiche" tabindex="-1">Die Bereiche <a class="header-anchor" href="#die-bereiche" aria-label="Permalink to &quot;Die Bereiche&quot;">​</a></h2>',7)),t("div",h,[t("a",u,[t("span",b,[i(n,{name:"layout-dashboard"})]),e[0]||(e[0]=t("span",{class:"tile-title"},"Übersicht",-1)),e[1]||(e[1]=t("span",{class:"tile-text"},"Paket auf einen Blick: Prüfungen, Freigaben, Wetter, Downloads.",-1))]),t("a",c,[t("span",k,[i(n,{name:"radar"})]),e[2]||(e[2]=t("span",{class:"tile-title"},"Intel",-1)),e[3]||(e[3]=t("span",{class:"tile-text"},"Bedrohungen freigeben – für alle oder einzelne Flights.",-1))]),t("a",f,[t("span",m,[i(n,{name:"pen-tool"})]),e[4]||(e[4]=t("span",{class:"tile-title"},"Planung",-1)),e[5]||(e[5]=t("span",{class:"tile-text"},"CAP, FLOT, Kill Box – taktische Grafiken für F10.",-1)),e[6]||(e[6]=t("span",{class:"tile-role"},"Designer",-1))]),t("a",p,[t("span",S,[i(n,{name:"timer"})]),e[7]||(e[7]=t("span",{class:"tile-title"},"Timing",-1)),e[8]||(e[8]=t("span",{class:"tile-text"},"H-Hour, TOT, Vul, Push, Tanker, Deconfliction.",-1))]),t("a",D,[t("span",z,[i(n,{name:"plane"})]),e[9]||(e[9]=t("span",{class:"tile-title"},"Flights",-1)),e[10]||(e[10]=t("span",{class:"tile-text"},"Route, Funk, Beladung, DTC, Angriff, Lineup Card.",-1))]),t("a",P,[t("span",F,[i(n,{name:"notebook-tabs"})]),e[11]||(e[11]=t("span",{class:"tile-title"},"Kneeboards",-1)),e[12]||(e[12]=t("span",{class:"tile-text"},"Seiten für alle: Deckblatt, SPINS, Comm Plan …",-1))]),t("a",K,[t("span",T,[i(n,{name:"network"})]),e[13]||(e[13]=t("span",{class:"tile-title"},"IADS",-1)),e[14]||(e[14]=t("span",{class:"tile-text"},"Das gegnerische Luftverteidigungsnetz bauen.",-1)),e[15]||(e[15]=t("span",{class:"tile-role"},"Designer",-1))])]),e[17]||(e[17]=r('<h2 id="liste-links" tabindex="-1">Liste links <a class="header-anchor" href="#liste-links" aria-label="Permalink to &quot;Liste links&quot;">​</a></h2><p>Was links steht, hängt vom Bereich ab: in <strong>Flights</strong> die Flights der Mission (Haken „nur spielbare“ blendet KI aus), in <strong>Intel</strong> die Stellungen, in <strong>Kneeboards</strong> die Seiten und Vorlagen. Mit den Pfeiltasten <kbd>↑</kbd> <kbd>↓</kbd> springst du durch die Flight-Liste. Die Pfeile ‹ › neben dem Namen im Flight-Panel (oder <kbd>⌥↑</kbd> <kbd>⌥↓</kbd>, unter Windows <kbd>Alt</kbd>) wechseln zum nächsten Flight und lassen den Reiter stehen – praktisch, um etwa die Beladung aller Flights nacheinander durchzugehen. Die Tasten <kbd>1</kbd> bis <kbd>6</kbd> wechseln den Bereich.</p><p>Ein <strong>DTC</strong>-Schild an einem Flight heißt: Er hat eine Cartridge.</p><h2 id="karte-und-panel" tabindex="-1">Karte und Panel <a class="header-anchor" href="#karte-und-panel" aria-label="Permalink to &quot;Karte und Panel&quot;">​</a></h2><p>Die Karte zeigt immer, was zum Bereich gehört – Routen, Threat-Ringe, Grafiken, das IADS-Netz. Darunter liegt das <strong>Panel</strong> mit den Details.</p><ul><li><strong>Höhe ändern:</strong> an der Trennlinie ziehen, Doppelklick setzt zurück.</li><li><strong>Lage des Panels:</strong> Oben rechts im Panel sitzen drei kleine Symbole; die gefüllte Fläche zeigt, wo das Panel liegt. Shardwing merkt sich die Lage je Bereich: Flights kann rechts stehen, Intel unten bleiben. <ul><li><strong>Unten:</strong> Panel unter der Karte, wie gewohnt.</li><li><strong>Rechts:</strong> Panel als Spalte neben der Karte, die Karte bekommt die ganze Höhe. Gut auf breiten Monitoren. Die Breite ziehst du am Griff, ein Doppelklick setzt sie zurück; breite Tabellen scrollen im Panel seitlich. In schmalen Fenstern fehlt dieses Symbol.</li><li><strong>Ganze Höhe:</strong> für lange Tabellen oder die Lineup-Card-Vorschau, auch mit <kbd>⌘⇧↵</kbd> / <kbd>Strg+Shift+Enter</kbd>.</li></ul></li><li><strong>Kleine Karte:</strong> Bei ganzer Höhe bleibt die Karte als kleines Fenster unten rechts und folgt dem gewählten Flight. Ein Klick darauf zeigt sie wieder groß, <strong>×</strong> blendet sie aus, <strong>▫ Karte</strong> holt sie zurück.</li><li><strong>Timing</strong> nutzt immer die ganze Höhe und zeigt ebenfalls die kleine Karte; ein Klick vergrößert sie an Ort und Stelle, <strong>▾ Klein</strong> verkleinert sie wieder. <strong>Kneeboards</strong> sind reine Dokumente und kommen ohne Karte aus.</li></ul><p>Alles zur Karte selbst (Ebenen, Messen, Bullseye): <a href="/start/karte">Die Karte</a>.</p><h2 id="ruckgangig" tabindex="-1">Rückgängig <a class="header-anchor" href="#ruckgangig" aria-label="Permalink to &quot;Rückgängig&quot;">​</a></h2><p>Jede Änderung lässt sich zurücknehmen: <kbd>⌘Z</kbd> / <kbd>Strg+Z</kbd>, wiederholen mit <kbd>⌘⇧Z</kbd> bzw. <kbd>Strg+Y</kbd>. In einem Textfeld gilt das Rückgängig des Feldes.</p><h2 id="schmale-fenster" tabindex="-1">Schmale Fenster <a class="header-anchor" href="#schmale-fenster" aria-label="Permalink to &quot;Schmale Fenster&quot;">​</a></h2><p>Wird das Fenster schmal, faltet Shardwing die Dateiknöpfe und Anzeige-Schalter ins <strong>Logo-Menü</strong>. Speichern bleibt immer sichtbar.</p><h2 id="suche" tabindex="-1">Suche <a class="header-anchor" href="#suche" aria-label="Permalink to &quot;Suche {#suche}&quot;">​</a></h2><p><kbd>⌘K</kbd> (Windows: <kbd>Strg+K</kbd>) oder <strong>Suchen …</strong> im Logo-Menü öffnet ein Suchfeld für alles, was einen Namen hat. Tippen, mit <kbd>↑</kbd> <kbd>↓</kbd> wählen, <kbd>↵</kbd> öffnet.</p><table tabindex="0"><thead><tr><th>Treffer</th><th>Was passiert</th></tr></thead><tbody><tr><td><strong>Flight</strong></td><td>Öffnet den Flight im Bereich Flights. Gefunden wird er über Callsign, Gruppenname, Flugzeugtyp oder Aufgabe.</td></tr><tr><td><strong>Wegpunkt</strong></td><td>Öffnet die Route des Flights und zeigt den Punkt auf der Karte. Gesucht wird nach dem Namen des Punktes.</td></tr><tr><td><strong>Intel</strong></td><td>Wählt die Stellung im Bereich Intel und zeigt sie auf der Karte, zum Beispiel mit „sa 11“.</td></tr><tr><td><strong>Planung</strong></td><td>Planungspunkte und benannte Grafiken, auf der Karte gezeigt.</td></tr><tr><td><strong>Kneeboards</strong></td><td>Öffnet das Dokument.</td></tr><tr><td><strong>Bereiche</strong></td><td>Wechselt den Bereich.</td></tr><tr><td><strong>Aktionen</strong></td><td>Zum gefundenen Flight: Route, Beladung, DTC, Lineup Card, Status, als Mission Designer auch duplizieren. Dazu Ausgeben, Speichern, Rückgängig. <kbd>⇥</kbd> zeigt nur Aktionen.</td></tr></tbody></table><p>Die Suche findet nur, was deine Rolle sieht: Als Flight tauchen nur freigegebene Bedrohungen auf.</p>',15))])}const R=a(g,[["render",_]]);export{C as __pageData,R as default};
